public LineBuffer readLineBuffer(int len)
        throws IOException
    {
        len=fillLine(len>0?len:_buf.length);

        if (len<0)
            return null;

        if (len==0)
        {
            _lineBuffer.size=0;
            return _lineBuffer;
        }

        _byteBuffer.setStream(_mark,len);

        _lineBuffer.size=0;
        int read=0;
        while(read<len && _reader.ready())
        {
            int r = _reader.read(_lineBuffer.buffer,
                                 read,
                                 len-read);
            if (r<=0)
                break;
            read+=r;
        }
        _lineBuffer.size=read;
        _mark=-1;

        return _lineBuffer;
    }

