        if (name.endsWith("/")) {
            name = name.substring(0, name.lastIndexOf("/"));
        }

        if (name.equals("")) {
            name = ROOT_MAPPING_PATH;
        }

        if (file.startsWith("/")) {
            file = file.substring(1);
