        String[] dirs = assetsMap.get(name);
        if (dirs != null) {
            for (String dir : dirs) {
                File f = FileUtils.getFile(dir, file);
                if (f.exists() && f.isFile()) {
                    try {
                        url = f.getAbsoluteFile().toURI().toURL();
                    } catch (MalformedURLException e) {
                        //
                    }
                }
                if (url == null) {
                    url = IOUtils.getResource(dir + file);
                }
                if (url != null) {
                    break;
                }
            }
        }
        return url;
    }

