private static Map<String, String> createInfoFieldKeyToAttrNameMap(
      VcfMeta vcfMeta, String entityTypeId) {
    Map<String, String> infoFieldIdToAttrNameMap =
        newHashMapWithExpectedSize(size(vcfMeta.getInfoMeta()));
    for (VcfMetaInfo info : vcfMeta.getInfoMeta()) {
      // according to the VCF standard it is allowed to have info columns with names that equal
      // default VCF cols.
      // rename these info columns in the meta data to prevent collisions.
      String postFix = "";
      switch (info.getId()) {
        case INTERNAL_ID:
        case CHROM:
        case ALT:
        case POS:
        case REF:
        case FILTER:
        case QUAL:
        case ID:
          postFix = '_' + entityTypeId;
          break;
        default:
          break;
      }

      String name = info.getId();
      if (NameValidator.KEYWORDS.contains(name)
          || NameValidator.KEYWORDS.contains(name.toUpperCase())) {
        name = name + '_';
      }
      infoFieldIdToAttrNameMap.put(info.getId(), name + postFix);
    }
    return infoFieldIdToAttrNameMap;
  }

