		Map<String,String> result = new TreeMap<> ();
		for( RoboconfTypeBean type : findAllTypes( appDirectory ).values()) {

			if( includeFacets && type.isFacet())
				result.put( type.getName(), type.getDescription());

			if( includeComponents && ! type.isFacet())
				result.put( type.getName(), type.getDescription());
		}

