public static double Cosh(double x, int nTerms) {
        if (nTerms < 2) return x;
        if (nTerms == 2) {
            return 1 + (x * x) / 2D;
        } else {

            double mult = x * x;
            double fact = 2;
            int factS = 4;
            double result = 1 + mult / fact;
            for (int i = 3; i <= nTerms; i++) {
                mult *= x * x;
                fact *= factS * (factS - 1);
                factS += 2;
                result += mult / fact;
            }

            return result;
        }
    }

