public static Set<BioPAXElement> runPathsFromToMultiSet(
		Set<Set<BioPAXElement>> sourceSets,
		Set<Set<BioPAXElement>> targetSets,
		Model model,
		LimitType limitType,
		int limit,
		Filter... filters)
	{
		Graph graph;

		if (model.getLevel() == BioPAXLevel.L3)
		{
			graph = new GraphL3(model, filters);
