          | CloudSdkOutOfDateException
          | ProcessHandlerException
          | CloudSdkNotFoundException
          | CloudSdkVersionFileException ex) {
        throw new GradleException("Failed to read project from gcloud config", ex);
      }
    }
    return configString;
  }

