            NativeOpsHolder.getInstance().getDeviceNativeOps().setDevice(currentDeviceId);
            Nd4j.getAffinityManager().attachThreadToDevice(Thread.currentThread().getId(), currentDeviceId);
        }

        return dstBuffer;
    }

