    int Eswap1 = con_salt[byteOne] << 4;

    byte key[] = new byte[8];

    for (int i = 0; i < key.length; i++) {
      key[i] = (byte) 0;
    }

    for (int i = 0; i < key.length && i < original.length; i++) {
      int iChar = (int) original[i];

      key[i] = (byte) (iChar << 1);
