            for (LayoutType.FIELD field : layout.getLAYOUT().getFIELD()) {
                LOGGER.info("> database field  : " + field.getNAME() + " / " + field.getSTYLE().getTYPE() + " / " + field.getSTYLE().getVALUELIST());
