public static long binValueOf(final String binaryStr) {
    if (Strings.isEmpty(binaryStr)) { return 0; }
    long value = 0;
    long height = 1;

    for (int i = binaryStr.length() - 1; i >= 0; i--) {
      if ('1' == binaryStr.charAt(i)) {
        value += height;
      }
      height *= 2;
    }
    return value;
  }

