			if (loggers.containsKey("/dev/null")) {
				logger = loggers.get("/dev/null");
			} else {
				try {
					logger = initLogger("/dev/null");
					loggers.put("/dev/null", logger);
				} catch (IOException e) {
					throw new ValidationException("Failed to setup logback", query, e);
				}
